  target: 'M12 21a9 9 0 100-18 9 9 0 000 18zM12 16a4 4 0 100-8 4 4 0 000 8zM12 12h.01',
  award: 'M12 14a6 6 0 100-12 6 6 0 000 12zM8.5 13l-1.5 8 5-3 5 3-1.5-8',
  handshake: 'M3 12l4-4 4 2 3-2 7 6-4 4-3-2-2 2-3-1-2 2-4-4 0-3zM3 12l-1 1M22 14l-1 1',
  briefcase: 'M3 8h18v12H3V8zM9 8V5h6v3M3 13h18',
  list: 'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',
  bolt: 'M13 2L4 14h7l-1 8 9-12h-7l1-8z',
  scale: 'M12 3v18M5 21h14M5 7h14M5 7l-3 7a3.5 3.5 0 006 0L5 7zM19 7l-3 7a3.5 3.5 0 006 0l-3-7z',
  leaf: 'M5 19c0-9 5-14 15-14 0 10-5 15-14 15M5 19l7-7',
  flow: 'M4 6h6v4H4V6zM14 14h6v4h-6v-4zM10 8h4a2 2 0 012 2v4',
} as const;

export type IconName = keyof typeof ICON_PATHS;

export function Icon({ name, size = 24, className }: IconProps & { name: IconName }) {
  return (
    <svg {...base(size)} className={className}>
      <path d={ICON_PATHS[name]} />
    </svg>
  );
}

/** A 44px pale-teal rounded square holding a line icon. */
export function IconTile({ name, className }: { name: IconName; className?: string }) {
  return (
    <span className={`icon-tile${className ? ` ${className}` : ''}`}>
      <Icon name={name} size={24} />
    </span>
  );
}

const PILLAR_ICONS: IconName[] = ['compass', 'graduation', 'code'];

export function PillarIcon({ kind }: { kind: number; size?: number }) {
  return <IconTile name={PILLAR_ICONS[kind % PILLAR_ICONS.length]} />;
}
"}

{"path": "src/components/Motifs.tsx", "content": "import * as React from 'react';

/** Background motif components (inline SVG, decorative). */

// Overlapping bell curves, stroked in light teal at low opacity.
export function BellCurveMotif({ className }: { className?: string }) {
  return (
    <svg
      className={className}
      viewBox="0 0 1200 400"
      preserveAspectRatio="xMidYMax slice"
      aria-hidden="true"
      focusable="false"
      fill="none"
      stroke="#5FC4C4"
      strokeWidth="2"
    >
      <path d="M-50 380 C150 380 250 60 450 60 S750 380 950 380" opacity="0.12" />
      <path d="M100 380 C300 380 400 100 600 100 S900 380 1100 380" opacity="0.12" />
      <path d="M300 380 C500 380 600 20 800 20 S1100 380 1300 380" opacity="0.12" />
      <path d="M-200 380 C0 380 100 140 300 140 S600 380 800 380" opacity="0.12" />
      <path d="M0 380H1200" opacity="0.12" />
    </svg>
  );
}

// Fine data-grid pattern.
export function DataGridMotif({ className }: { className?: string }) {
  const id = `grid-${React.useId().replace(/[^a-zA-Z0-9]/g, '')}`;
  return (
    <svg className={className} width="100%" height="100%" aria-hidden="true" focusable="false">
      <defs>
        <pattern id={id} width="32" height="32" patternUnits="userSpaceOnUse">
          <path d="M32 0H0V32" fill="none" stroke="#5FC4C4" strokeWidth="1" opacity="0.12" />
          <circle cx="0" cy="0" r="1.5" fill="#5FC4C4" opacity="0.12" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill={`url(#${id})`} />
    </svg>
  );
}

// Small bell-curve illustration for the 404 page
export function BellCurveIllustration({ className }: { className?: string }) {
  return (
    <svg
