{"path": "src/styles/global.css", "content": "/* Global styles: The Bayes Group. Tokens live in theme.css. */
*, *::before, *::after { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  overflow-x: hidden;
}
/* `clip` keeps the sticky header working: `hidden` on body would make it a scroll container. */
body { overflow-x: clip; }

body {
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-white);
}

img, svg, video { max-width: 100%; }
img { height: auto; }
picture { display: block; }

h1, h2, h3, h4, h5, h6,
.hero h1, .pillar-card h3, .service-item h3, .card h3, .eyebrow-heading {
  font-family: Georgia, "Times New Roman", var(--font-serif);
  color: var(--color-navy);
  margin: 0 0 var(--space-3);
  font-weight: 600;
  overflow-wrap: anywhere;
}
h1 { font-size: var(--text-h1); line-height: 1.22; }
h2 { font-size: var(--text-h2); line-height: 1.27; margin-bottom: var(--space-4); }
h3 { font-size: var(--text-h3); line-height: 1.4; }
p { margin: 0 0 var(--space-4); overflow-wrap: anywhere; }
ul, ol { margin: 0; padding: 0; }

a { color: var(--color-accent-strong); text-decoration: none; overflow-wrap: anywhere; }
a:hover { text-decoration: underline; }

button, input, select, textarea { font-family: inherit; font-size: var(--text-body); }
button { cursor: pointer; }

.visually-hidden {
  position: absolute; width: 1px; height: 1px; margin: -1px; padding: 0;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}

:focus-visible { outline: var(--focus-ring); outline-offset: 2px; }
.on-dark :focus-visible, .band-navy :focus-visible, .band-navy-deep :focus-visible,
.hero :focus-visible, .cta-band :focus-visible, .site-footer :focus-visible, .premium :focus-visible {
  outline-color: var(--color-accent-light);
}
.cta-light :focus-visible { outline-color: var(--color-accent-strong); }

.skip-link {
  position: absolute; left: -999px; top: 8px;
  background: var(--color-navy); color: var(--color-white);
  padding: var(--space-3) var(--space-4); border-radius: var(--radius-sm); z-index: 100;
}
.skip-link:focus { left: 8px; }

main:focus { outline: none; }

input:focus, select:focus, textarea:focus,
input:focus-visible, select:focus-visible, textarea:focus-visible,
button:focus-visible, a:focus-visible {
  outline: 3px solid var(--color-accent-strong); outline-offset: 2px;
}
.band-navy a:focus-visible, .band-navy-deep a:focus-visible, .hero a:focus-visible,
.cta-band a:focus-visible, .site-footer a:focus-visible, .premium a:focus-visible {
  outline: 3px solid var(--color-accent-light); outline-offset: 2px;
}
.cta-light a:focus-visible { outline-color: var(--color-accent-strong); }

.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; width: 100%; }

/* Sections */
.section { padding-top: var(--space-8); padding-bottom: var(--space-8); }
.section-surface { background: var(--color-surface-teal); }

.eyebrow {
  font-family: var(--font-mono);
  font-size: var(--text-eyebrow); line-height: 1.5; text-transform: uppercase;
  font-weight: 600; letter-spacing: .12em; color: var(--color-accent-strong); margin: 0 0 var(--space-3);
}
.band-navy .eyebrow, .band-navy-deep .eyebrow, .hero .eyebrow, .cta-band .eyebrow,
.premium .eyebrow, .site-footer .eyebrow { color: var(--color-accent-light); }
.cta-light .eyebrow { color: var(--color-accent-strong); }
.lead { font-size: var(--text-lead); line-height: 1.6; }
.muted { color: var(--color-muted); }
.monospace { font-family: var(--font-mono); }

/* Navy bands with motifs */
.band-navy { position: relative; overflow: hidden; background: var(--color-navy); color: var(--color-white); }
.band-navy-deep { position: relative; overflow: hidden; background: var(--color-navy-deep); color: var(--color-white); }
.band-navy h2, .band-navy h3, .band-navy-deep h2, .band-navy-deep h3 { color: var(--color-white); }
.band-motif {
  position: absolute; inset: 0; width: 100%; height: 100%;
  pointer-events: none; z-index: 0;
}
.band-content { position: relative; z-index: 1; }
.band-navy a:not(.btn), .band-navy-deep a:not(.btn) { color: var(--color-accent-light); }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; text-align: center;
  min-height: 48px; padding: 0 24px; border-radius: var(--radius-sm);
  font-family: var(--font-sans); font-weight: 600; font-size: 16px; line-height: 1.2;
  border: 1.5px solid transparent; cursor: pointer; text-decoration: none;
  transition: background-color 150ms ease, color 150ms ease, transform 150ms ease;
}
.btn:hover { text-decoration: none; }
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--color-accent-strong); color: var(--color-white); }
.btn-primary:hover { background: var(--color-accent-strong-hover); color: var(--color-white); }
.btn-secondary { background: var(--color-white); color: var(--color-navy); border-color: var(--color-navy); }
.btn-secondary:hover { background: var(--color-surface); }
.btn-on-dark, .band-navy a.btn-on-dark, .band-navy-deep a.btn-on-dark { background: var(--color-white); color: var(--color-navy); }
.btn-on-dark:hover { background: var(--color-surface-teal); color: var(--color-navy); }
.btn-on-dark-secondary, .band-navy a.btn-on-dark-secondary { background: transparent; color: var(--color-white); border-color: var(--color-white); }
.btn-on-dark-secondary:hover { background: rgba(255,255,255,.1); color: var(--color-white); }
.btn-header { min-height: 44px; }
.btn-block { width: 100%; }

/* Icons */
.icon-tile {
  display: inline-flex; align-items: center; justify-content: center; flex: none;
  width: 44px; height: 44px; border-radius: 10px;
  background: var(--color-tile); color: var(--color-accent-strong);
}
.icon-tile svg { display: block; }

/* Header */
.site-header {
  position: sticky; top: 0; z-index: 50; height: var(--header-h);
  background: var(--color-white); border-bottom: 1px solid transparent;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}
.site-header.is-scrolled { background: var(--color-white); border-bottom-color: var(--color-hairline); box-shadow: 0 1px 0 var(--color-hairline); }
.header-inner { display: flex; align-items: center; justify-content: space-between; height: 100%; gap: var(--space-4); }
.wordmark { display: inline-flex; align-items: center; gap: 8px; color: var(--color-navy); text-decoration: none; min-height: 44px; white-space: nowrap; }
.wordmark:hover { text-decoration: none; }
.wordmark-text { font-family: var(--font-serif); font-weight: 600; font-size: 20px; }
.wordmark-dark { color: var(--color-white); }
.wordmark-mark { flex: none; }

.nav-desktop { display: none; align-items: center; gap: var(--space-1); }
.nav-link {
  display: inline-flex; align-items: center; min-height: 44px; padding: 0 var(--space-3);
  color: var(--color-navy); font-weight: 500; border-bottom: 2px solid transparent; text-decoration: none;
}
.nav-link:hover { text-decoration: none; border-bottom-color: var(--color-hairline); }
.nav-link[aria-current="page"] { border-bottom-color: var(--color-accent); }
.nav-desktop .btn { margin-left: var(--space-3); }

.menu-toggle {
  display: inline-flex; align-items: center; gap: var(--space-2);
  background: none; border: none; color: var(--color-navy); font-weight: 600;
  min-height: 44px; min-width: 44px; padding: 0 var(--space-2);
}
.nav-mobile {
  position: absolute; top: 100%; left: 0; right: 0; background: var(--color-white);
  border-bottom: 1px solid var(--color-hairline); box-shadow: var(--shadow-card);
  padding: var(--space-3) 24px var(--space-5);
}
.nav-mobile ul { list-style: none; display: flex; flex-direction: column; gap: var(--space-1); }
.nav-mobile .nav-link { display: flex; min-height: 48px; width: 100%; }
.nav-mobile li:last-child { margin-top: var(--space-3); }

/* Hero (photo) */
.hero { position: relative; overflow: hidden; background: var(--color-navy); color: var(--color-white); padding: var(--space-8) 0; }
.hero h1 { font-family: Georgia, "Times New Roman", var(--font-serif); color: var(--color-white); font-size: var(--text-hero); line-height: 1.2; }
.hero p.lead { color: var(--color-muted-on-dark); max-width: 640px; }
.hero-photo-section {
  display: flex; align-items: flex-end; min-height: 560px;
  padding: var(--space-8) 0 112px;
}
.hero-photo { position: absolute; inset: 0; width: 100%; height: 100%; }
.hero-photo img, .banner-photo img { width: 100%; height: 100%; object-fit: cover; display: block; }
.hero-overlay { position: absolute; inset: 0; background: var(--overlay-hero-phone); pointer-events: none; }
.hero-motif { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; }
.hero-grid { position: relative; z-index: 1; display: block; }
.hero-text { max-width: 720px; }
.hero-buttons { display: flex; flex-direction: column; gap: var(--space-3); margin-top: var(--space-5); }
.hero-buttons .btn { width: 100%; }

.page-hero { padding: var(--space-8) 0; }
.page-hero h1 { font-size: var(--text-h1); }
.hero-diagram { margin-top: var(--space-7); }

/* Credibility strip */
.cred-strip { position: relative; z-index: 2; margin-top: -48px; }
.cred-bar {
  list-style: none; display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-5) var(--space-4);
  background: var(--color-white); border: 1px solid var(--color-hairline); border-radius: var(--radius-md);
  box-shadow: var(--shadow-card); padding: var(--space-5);
}
.cred-item { display: flex; flex-direction: column; align-items: flex-start; gap: var(--space-3); color: var(--color-navy); font-weight: 600; font-size: 1rem; line-height: 1.4; }

/* Who we serve */
.who-serve .eyebrow { margin-bottom: var(--space-5); }
.panel-grid { display: grid; gap: var(--space-5); }
.panel {
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--color-white); border: 1px solid var(--color-hairline); border-radius: var(--radius-md);
  box-shadow: var(--shadow-card); transition: transform 150ms ease, box-shadow 150ms ease;
}
.panel:hover { transform: translateY(-2px); box-shadow: var(--shadow-card-hover); }
.panel-photo img { width: 100%; height: 220px; object-fit: cover; display: block; }
.panel-body { display: flex; flex-direction: column; align-items: flex-start; flex: 1; padding: var(--space-5); }
.panel-body p { flex: 1; }
.panel.premium { background: var(--color-navy-deep); color: var(--color-white); border-color: var(--color-accent); }
.panel.premium h2 { color: var(--color-white); }
.panel.premium a { color: var(--color-accent-light); }
.premium-label {
  display: inline-block; background: var(--color-accent-light); color: var(--color-navy);
  font-family: var(--font-mono); font-size: var(--text-small); font-weight: 700; text-transform: uppercase;
  letter-spacing: .08em; line-height: 1; padding: 6px 12px; border-radius: var(--radius-pill);
  margin: 0 0 var(--space-3);
}

/* Systems band */
.systems-band { padding: var(--space-8) 0; }
.systems-content { display: grid; gap: var(--space-6); margin: var(--space-7) 0 var(--space-6); }
.capabilities { display: grid; gap: var(--space-3); align-content: center; }
.capability {
  display: flex; gap: var(--space-4); align-items: flex-start;
  background: var(--color-navy-raised); border: 1px solid rgba(95,196,196,.25);
  border-radius: var(--radius-md); padding: var(--space-4);
}
.capability h3 { color: var(--color-white); margin-bottom: var(--space-1); font-size: 1.125rem; }
.capability p { color: var(--color-muted-on-dark); margin: 0; font-size: 1rem; }
.text-link { display: inline-flex; align-items: center; gap: 6px; min-height: 44px; font-weight: 600; }
.text-link svg { transition: transform 150ms ease; }
.text-link:hover svg { transform: translateX(4px); }

/* Cards */
.card {
  background: var(--color-white); border: 1px solid var(--color-hairline); border-radius: var(--radius-md);
  padding: 24px; box-shadow: var(--shadow-card);
  transition: transform 150ms ease, box-shadow 150ms ease;
}
.card:hover { transform: translateY(-2px); box-shadow: var(--shadow-card-hover); }
.grid { display: grid; gap: var(--space-4); }

/* Pillars */
.pillars { display: grid; gap: var(--space-5); margin-top: var(--space-7); }
.pillar-card { display: flex; flex-direction: column; padding: 0; overflow: hidden; }
.strip-photo img { width: 100%; height: 160px; object-fit: cover; display: block; }
.pillar-body { display: flex; flex-direction: column; align-items: flex-start; flex: 1; padding: var(--space-5); }
.pillar-body .icon-tile { margin-bottom: var(--space-4); }
.pillar-body p { flex: 1; }
.pillar-title {
  font-family: var(--font-serif);
  font-size: var(--text-h3);
  font-weight: 600;
  color: var(--color-navy);
  margin: 0 0 var(--space-2);
}

/* Steps */
.how-we-work { position: relative; }
.steps { list-style: none; display: grid; gap: var(--space-5); margin-top: var(--space-7); }
.steps li { position: relative; }
.step-num {
  display: flex; align-items: center; justify-content: center; width: 48px; height: 48px; border-radius: 50%;
  background: var(--color-accent-strong); color: var(--color-white); font-family: var(--font-serif);
  font-weight: 600; font-size: 1.25rem; margin-bottom: var(--space-3);
}
.operate-step {
  display: flex; gap: var(--space-4); align-items: flex-start; margin-top: var(--space-6);
  background: var(--color-surface-teal); border: 1px solid var(--color-hairline); border-radius: var(--radius-md);
  padding: var(--space-5);
}
.operate-step h3 { margin-bottom: var(--space-1); }
.operate-step p { margin: 0; }

/* Examples */
.example-cards { display: grid; gap: var(--space-5); margin-top: var(--space-7); }
.example-card { display: flex; flex-direction: column; align-items: flex-start; }
.example-card .tag {
  display: inline-block; background: var(--color-tile); color: var(--color-accent-strong);
  font-family: var(--font-mono); font-size: 0.75rem; font-weight: 600; text-transform: uppercase; letter-spacing: .08em;
  padding: 4px 12px; border-radius: var(--radius-pill); margin-bottom: var(--space-3);
}
.example-card .industry { font-family: var(--font-mono); font-size: var(--text-small); color: var(--color-muted); margin: 0 0 var(--space-1); }
.example-card dl { margin: 0 0 var(--space-4); }
.example-card dt {
  font-family: var(--font-mono); font-size: 0.75rem; text-transform: uppercase; letter-spacing: .08em;
  font-weight: 600; color: var(--color-accent-strong); margin: var(--space-3) 0 var(--space-1);
}
.example-card dd { margin: 0; }
.example-card .note {
  margin: auto 0 0; padding-top: var(--space-3); border-top: 1px solid var(--color-hairline);
  width: 100%; font-size: var(--text-small); color: var(--color-muted);
}

/* Testimonial */
.testimonial { padding: var(--space-8) 0; text-align: center; }
.testimonial-figure { max-width: 800px; margin: 0 auto; }
.testimonial-note { font-size: var(--text-small); color: var(--color-muted-on-dark); font-style: italic; }
.testimonial blockquote {
  margin: var(--space-4) 0; font-family: Georgia, "Times New Roman", var(--font-serif);
  font-size: 1.5rem; line-height: 1.4; color: var(--color-white);
}
.testimonial figcaption { font-family: var(--font-mono); font-size: var(--text-small); color: var(--color-accent-light); }

/* Why */
.why-layout { display: grid; gap: var(--space-6); align-items: center; }
.why-photo img { width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; border-radius: var(--radius-md); display: block; box-shadow: var(--shadow-card); }
.why-list { display: grid; gap: var(--space-5); margin-top: var(--space-5); }
.why-point { display: flex; gap: var(--space-3); align-items: flex-start; }
.why-point h3 { margin-bottom: var(--space-1); }
.why-point p { margin: 0; }

/* CTA band */
.cta-band { position: relative; overflow: hidden; background: var(--color-navy-deep); color: var(--color-white); padding: var(--space-8) 0; text-align: center; }
.cta-band h2 { color: var(--color-white); }
.cta-band .btn { margin-top: var(--space-3); }
.cta-light { background: var(--color-surface-teal); color: var(--color-text); }
.cta-light h2 { color: var(--color-navy); }
.cta-light .btn-primary { color: var(--color-white); }

/* Page header (plain) */
.page-head { padding-top: var(--space-8); padding-bottom: var(--space-5); }
.page-head p { max-width: 640px; }

/* Services */
.service-section { scroll-margin-top: 96px; }
.service-layout { display: grid; gap: var(--space-5); align-items: center; }
.service-photo img { width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; border-radius: var(--radius-md); display: block; box-shadow: var(--shadow-card); }
.service-items { display: grid; gap: var(--space-4); margin-top: var(--space-7); }
.service-item { display: flex; gap: var(--space-4); align-items: flex-start; }
.service-item h3 { margin-bottom: var(--space-2); }
.service-item p { margin: 0 0 var(--space-2); }
.engagement { display: flex; align-items: center; gap: var(--space-2); color: var(--color-accent-strong); font-weight: 600; margin: var(--space-5) 0 0; }
.engagement svg { flex: none; }

/* Systems page */
.system-layout { display: grid; gap: var(--space-6); align-items: center; }
.icon-list { list-style: none; display: grid; gap: var(--space-3); margin-top: var(--space-5); }
.icon-list li { display: flex; gap: var(--space-3); align-items: flex-start; }
.icon-bullet { display: inline-flex; flex: none; color: var(--color-accent-strong); margin-top: 2px; }
.system-art { display: flex; justify-content: center; }
.section-illustration {
  width: 100%; max-width: 320px; height: auto;
  background: var(--color-white); border: 1px solid var(--color-hairline); border-radius: var(--radius-md);
  padding: var(--space-4); box-shadow: var(--shadow-card);
}
.section-surface .section-illustration { background: var(--color-white); }
.deliverables { padding: var(--space-8) 0; }
.deliverable-grid { display: grid; gap: var(--space-4); margin-top: var(--space-7); }
.deliverable-card {
  display: flex; align-items: center; gap: var(--space-4);
  background: var(--color-navy-raised); border: 1px solid rgba(95,196,196,.25);
  border-radius: var(--radius-md); padding: var(--space-5); color: var(--color-white);
}
.deliverable-name { color: var(--color-white); font-size: 0.9375rem; line-height: 1.4; }

/* Engagements */
.tier-grid { display: grid; gap: var(--space-5); }
.tier-card {
  display: flex; flex-direction: column; overflow: hidden;
  background: var(--color-white); border: 1px solid var(--color-hairline); border-radius: var(--radius-md);
  box-shadow: var(--shadow-card); transition: transform 150ms ease, box-shadow 150ms ease;
  scroll-margin-top: 96px;
}
.tier-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-card-hover); }
.tier-body { display: flex; flex-direction: column; flex: 1; padding: var(--space-5); }
.tier-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); margin-bottom: var(--space-4); }
.tier-head .premium-label { margin: 0; }
.tier-card h2 { margin-bottom: var(--space-1); }
.tier-card .audience { color: var(--color-muted); margin-bottom: var(--space-2); }
.tier-card .timeline { display: flex; align-items: center; gap: var(--space-2); font-family: var(--font-mono); font-weight: 600; color: var(--color-accent-strong); margin-bottom: var(--space-4); }
.tier-card h3 { font-size: 1.0625rem; margin-bottom: var(--space-3); }
.check-list { list-style: none; display: grid; gap: var(--space-3); margin-bottom: var(--space-5); flex: 1; align-content: start; }
.check-list li { display: flex; gap: var(--space-3); align-items: flex-start; }
.check-list svg { flex: none; color: var(--color-accent-strong); margin-top: 2px; }
.tier-card .btn { align-self: flex-start; }
.tier-photo img { width: 100%; height: 220px; object-fit: cover; display: block; }
.tier-premium { margin-top: var(--space-6); }
.tier-card.premium {
  background: var(--color-navy-deep); color: var(--color-white);
  border: 2px solid var(--color-accent); box-shadow: var(--shadow-card-hover);
}
.tier-card.premium h2, .tier-card.premium h3 { color: var(--color-white); }
.tier-card.premium .audience { color: var(--color-muted-on-dark); }
.tier-card.premium .timeline { color: var(--color-accent-light); }
.tier-card.premium .check-list svg { color: var(--color-accent-light); }
.tier-card.premium .btn-on-dark { background: var(--color-white); color: var(--color-navy); }
.not-sure { padding: var(--space-7) 0; text-align: center; }
.not-sure p { margin: 0; font-size: var(--text-lead); }

/* Training */
.training-banner {
  position: relative; overflow: hidden; background: var(--color-navy); color: var(--color-white);
  display: flex; align-items: flex-end; min-height: 320px; padding: var(--space-8) 0;
}
.banner-photo { position: absolute; inset: 0; width: 100%; height: 100%; }
.banner-text { position: relative; z-index: 1; }
.training-banner h1 { color: var(--color-white); }
.training-banner .eyebrow { color: var(--color-accent-light); }
.training-banner .lead { color: var(--color-muted-on-dark); max-width: 640px; margin: 0; }
.filter-bar { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-bottom: var(--space-4); }
.filter-bar button {
  min-height: 44px; padding: 0 var(--space-4); border-radius: var(--radius-sm);
  background: var(--color-white); color: var(--color-navy); border: 1.5px solid var(--color-input-border);
  font-weight: 600; transition: background-color 150ms ease, color 150ms ease;
}
.filter-bar button:hover { background: var(--color-surface-teal); }
.filter-bar button.filter-selected, .filter-bar button[aria-pressed="true"] {
  background: var(--color-navy); color: var(--color-white); border-color: var(--color-navy);
}
.course-count { color: var(--color-muted); margin-bottom: var(--space-5); }
.course-grid { display: grid; gap: var(--space-4); }
.course-card { display: flex; flex-direction: column; align-items: flex-start; height: 100%; }
.course-card .icon-tile { margin-bottom: var(--space-3); }
.course-header { display: flex; flex-wrap: wrap; gap: var(--space-2); align-items: center; margin-bottom: var(--space-3); }
.audience-chip {
  background: var(--color-chip); color: var(--color-accent-strong); font-size: var(--text-small);
  font-weight: 600; padding: 2px 10px; border-radius: var(--radius-pill);
}
.format { color: var(--color-muted); font-size: var(--text-small); }
.course-card .duration { color: var(--color-muted); font-size: var(--text-small); }
.course-card hr { border: 0; border-top: 1px solid var(--color-hairline); margin: var(--space-4) 0; width: 100%; }
.learn-title { font-weight: 600; color: var(--color-navy); margin-bottom: var(--space-2); }
.course-card ul { padding-left: 20px; }
.course-card li { margin-bottom: var(--space-1); }
.empty-state { text-align: center; padding: var(--space-7) 0; }

/* About */
.split { display: grid; gap: var(--space-6); align-items: center; }
.split-photo img { width: 100%; height: auto; aspect-ratio: 4 / 3; object-fit: cover; border-radius: var(--radius-md); display: block; box-shadow: var(--shadow-card); }
.about-grid { display: grid; gap: var(--space-4); margin-top: var(--space-7); }
.founder-top { display: flex; align-items: center; gap: var(--space-4); margin-bottom: var(--space-4); }
.avatar { width: 72px; height: 72px; flex: none; }
.avatar-caption { margin: var(--space-1) 0 0; font-size: var(--text-small); color: var(--color-muted); }
.founder-card .placeholder-tag {
  display: inline-block; background: var(--color-placeholder-bg); color: var(--color-placeholder-tag);
  font-size: var(--text-small); font-weight: 600; padding: 2px 10px; border-radius: var(--radius-pill);
}
.placeholder-note { font-style: italic; color: var(--color-placeholder-tag); font-size: var(--text-small); margin: var(--space-3) 0 0; }
.founder-role { color: var(--color-muted); font-weight: 600; }
.founder-card ul { padding-left: 20px; margin-bottom: var(--space-4); }
.value-card .icon-tile { margin-bottom: var(--space-4); }

/* Contact */
.contact-grid { display: grid; gap: var(--space-6); padding-bottom: var(--space-8); }
.contact-info { grid-column: 1 / -1; }
.contact-form-card { max-width: 640px; width: 100%; }
.contact-page .field { margin-bottom: var(--space-5); display: flex; flex-direction: column; gap: var(--space-2); }
.contact-page label { font-weight: 600; color: var(--color-navy); display: flex; align-items: center; gap: var(--space-2); }
.field-head { display: flex; align-items: center; gap: var(--space-2); }
.form-note { font-size: var(--text-small); margin-bottom: var(--space-5); }
.required-tag {
  font-size: 0.75rem; font-weight: 600; color: var(--color-muted); border: 1px solid var(--color-input-border);
  border-radius: var(--radius-pill); padding: 0 8px; line-height: 1.5;
}
.form-control {
  border: 1.5px solid var(--color-input-border);
  border-radius: var(--radius-sm);
  padding: 10px 14px;
  background: var(--color-white);
  color: var(--color-text);
  width: 100%;
  min-height: 48px;
}
.form-control:focus,
.form-control:focus-visible {
  border-color: var(--color-accent-strong);
  outline: 3px solid var(--color-accent-strong);
  outline-offset: 2px;
}
.form-control[aria-invalid="true"] {
  border-color: var(--color-error);
}
.contact-page textarea { min-height: 140px; resize: vertical; }
.contact-page input::placeholder { color: var(--color-muted); }
.contact-page .error-message {
  display: flex; align-items: flex-start; gap: 6px; color: var(--color-error); font-size: var(--text-small); margin: 0;
}
.contact-page .error-message svg { flex: none; margin-top: 2px; }
.success-banner {
  display: flex; align-items: center; gap: var(--space-3); background: var(--color-success-bg);
  color: var(--color-success); border-radius: var(--radius-sm); padding: var(--space-4); margin-bottom: var(--space-5);
  font-weight: 600;
}
.success-banner svg { flex: none; }
.contact-page button[type="submit"] { width: 100%; }
.contact-aside {
  background: var(--color-surface-teal); border: 1px solid var(--color-hairline); border-radius: var(--radius-md);
  padding: var(--space-5); align-self: start;
}
.contact-aside img { border-radius: var(--radius-sm); width: 100%; height: 220px; object-fit: cover; margin-bottom: var(--space-5); display: block; }
.next-steps { padding-left: 24px; }
.next-steps li { margin-bottom: var(--space-2); }

/* Not found */
.notfound-page { padding: var(--space-8) 0; }
.notfound-art { width: 100%; max-width: 320px; height: auto; display: block; margin-bottom: var(--space-5); }
.notfound-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-4); margin-top: var(--space-5); }

/* Footer */
.site-footer { background: var(--color-navy-deep); color: var(--color-white); padding: var(--space-8) 0 var(--space-6); }
.footer-inner { display: grid; gap: var(--space-6); }
.footer-brand p { color: var(--color-muted-on-dark); margin: var(--space-3) 0 var(--space-2); }
.footer-email { color: var(--color-accent-light); font-weight: 600; }
.footer-heading {
  font-family: var(--font-mono); font-size: var(--text-eyebrow); text-transform: uppercase; letter-spacing: .12em;
  color: var(--color-accent-light); margin: 0 0 var(--space-3); line-height: 1.5;
}
.footer-col ul, .footer-nav ul { list-style: none; display: grid; gap: var(--space-1); }
.footer-col a, .footer-nav a { color: var(--color-white); display: inline-flex; align-items: center; min-height: 40px; }
.footer-col a:hover, .footer-nav a:hover { color: var(--color-accent-light); }
.footer-bottom { margin-top: var(--space-7); padding-top: var(--space-5); border-top: 1px solid rgba(255,255,255,.14); }
.footer-copy { color: var(--color-muted-on-dark); margin: 0; font-size: var(--text-small); }

/* Architecture diagram */
.arch-diagram { width: 100%; }
.arch-svg { display: block; width: 100%; height: auto; }
.arch-stacked { display: none; max-width: 420px; margin: 0 auto; }
.diagram-text { font-family: var(--font-mono); }
@media (max-width: 767px) {
  .arch-wide { display: none; }
  .arch-stacked { display: block; }
}

p a:not(.btn) { text-decoration: underline; }

@media (min-width: 768px) {
  .cred-bar { grid-template-columns: repeat(4, 1fr); }
  .pillars, .course-grid, .about-grid.values, .service-items, .deliverable-grid { grid-template-columns: repeat(2, 1fr); }
  .steps { grid-template-columns: repeat(2, 1fr); }
  .why-list { grid-template-columns: repeat(2, 1fr); }
  .about-grid.founders { grid-template-columns: repeat(2, 1fr); }
  .example-cards { grid-template-columns: repeat(2, 1fr); }
  .hero-buttons { flex-direction: row; }
  .hero-buttons .btn { width: auto; }
}

@media (min-width: 1024px) {
  .container { padding: 0 40px; }
  body { font-size: 1.125rem; }
  h1 { font-size: 3rem; line-height: 1.17; }
  h2 { font-size: 2.625rem; line-height: 1.19; }
  h3 { font-size: 1.375rem; }
  .lead { font-size: 1.3125rem; }
  .section, .page-hero, .systems-band, .deliverables, .testimonial, .cta-band { padding-top: var(--space-10); padding-bottom: var(--space-10); }
  .hero h1 { font-size: 3.75rem; line-height: 1.12; }
  .page-hero h1 { font-size: 3rem; line-height: 1.17; }
  .hero-photo-section { align-items: center; min-height: 680px; padding: var(--space-10) 0 144px; }
  .hero-overlay { background: var(--overlay-hero); }
  .cred-bar { padding: var(--space-5); }
  .cred-item { flex-direction: row; align-items: center; }
  .panel-grid { grid-template-columns: 7fr 5fr; gap: var(--space-6); align-items: stretch; }
  .panel-photo img { height: 280px; }
  .panel-body { padding: var(--space-6); }
  .systems-content { grid-template-columns: 7fr 5fr; align-items: center; gap: var(--space-6); }
  .pillars { grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
  .example-cards { grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
  .steps { grid-template-columns: repeat(4, 1fr); gap: var(--space-6); position: relative; }
  .steps::before { content: ""; position: absolute; top: 24px; left: 12.5%; right: 12.5%; height: 2px; background: var(--color-accent); z-index: 0; }
  .step-num { position: relative; z-index: 1; box-shadow: 0 0 0 8px var(--color-white); }
  .why-layout { grid-template-columns: 5fr 7fr; gap: var(--space-7); }
  .why-list { margin-top: var(--space-5); }
  .service-layout { grid-template-columns: 5fr 7fr; gap: var(--space-7); }
  .service-items { grid-template-columns: repeat(2, 1fr); gap: var(--space-5); }
  .system-layout { grid-template-columns: 7fr 5fr; gap: var(--space-7); }
  .system-section.flip .system-text { order: 2; }
  .system-section.flip .system-art { order: 1; }
  .deliverable-grid { grid-template-columns: repeat(3, 1fr); gap: var(--space-5); }
  .tier-grid { grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
  .tier-body { padding: var(--space-6); }
  .tier-card.premium { display: grid; grid-template-columns: 5fr 7fr; }
  .tier-card.premium .tier-photo { height: 100%; }
  .tier-card.premium .tier-photo img { height: 100%; min-height: 360px; }
  .tier-card.premium .tier-body { padding: var(--space-7); }
  .course-grid { grid-template-columns: repeat(3, 1fr); }
  .about-grid.values { grid-template-columns: repeat(4, 1fr); }
  .split { grid-template-columns: 5fr 7fr; gap: var(--space-7); }
  .contact-grid { grid-template-columns: 7fr 5fr; gap: var(--space-6); align-items: start; }
  .testimonial blockquote { font-size: 2rem; }
  .nav-desktop { display: flex; }
  .menu-toggle, .nav-mobile { display: none; }
  .footer-inner { grid-template-columns: 2fr 1fr 1fr 1fr; gap: var(--space-6); }
  .training-banner { min-height: 400px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
    animation: none !important;
    transform: none !important;
    scroll-behavior: auto !important;
  }
}
"}

