{
  "issues": [
    {
      "issue": "The Engagements page renders tier cards as <article> elements with id attributes, but the acceptance tests expect the Enterprise tier card to be an <article id="enterprise">. The task only requires the enterprise card to have id "enterprise"; however, the test also checks for a Premium label and for an <img> with src containing "enterprise-atrium". The current implementation fulfills these but incorrectly places the Premium label inside the .tier-body instead of as a separate visual element as required by design tokens, and the layout does not ensure the <article> element is styled with the required navy background and teal outline (dark card). The test also expects the "Not sure which fits?" line to be after the tiers, but the current component renders it inside a separate <section> that may not follow the tier elements due to extra whitespace or missing wrapping, causing possible ordering failures.",
      "task_quote": "The Engagements page renders tier cards as <article> elements with id attributes, but the acceptance tests expect the Enterprise tier card to be an <article id="enterprise">. The task only requires the enterprise card to have id "enterprise"; however, the test also checks for a Premium label and for an <img> with src containing "enterprise-atrium". The current implementation fulfills these but incorrectly places the Premium label inside the .tier-body instead of as a separate visual element as required by design tokens, and the layout does not ensure the <article> element is styled with the required navy background and teal outline (dark card). The test also expects the "Not sure which fits?" line to be after the tiers, but the current component renders it inside a separate <section> that may not follow the tier elements due to extra whitespace or missing wrapping, causing possible ordering failures.",
      "test": "/*
REPRO issue for Engagements page
The Engagements page renders tier cards as <article> elements with id attributes, but the acceptance tests expect the Enterprise tier card to be an <article id=\"enterprise\">. The task only requires the enterprise card to have id \"enterprise\"; however, the test also checks for a Premium label and for an <img> with src containing \"enterprise-atrium\". The current implementation fulfills these but incorrectly places the Premium label inside the .tier-body instead of as a separate visual element as required by design tokens, and the layout does not ensure the <article> element is styled with the required navy background and teal outline (dark card). The test also expects the \"Not sure which fits?\" line to be after the tiers, but the current component renders it inside a separate <section> that may not follow the tier elements due to extra whitespace or missing wrapping, causing possible ordering failures.
*/

/** @jest-environment jsdom */
import * as React from 'react';
import { render, screen, within } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import EngagementsPage from '../src/pages/EngagementsPage';

test('REPRO: Enterprise tier card has correct id, premium label placement, image src, dark card class, and ordering', () => {
  const { container } = render(
    <MemoryRouter>
      <EngagementsPage />
    </MemoryRouter>,
  );
  const article = container.querySelector('article#enterprise');
  expect(article).not.toBeNull();
  // Image source contains "enterprise-atrium"
  const img = article?.querySelector('img');
  expect(img).not.toBeNull();
  const src = (img as HTMLImageElement).src;
  expect(src).toMatch(/enterprise-atrium/);
  // Premium label must not be inside .tier-body
  const premium = within(article!).getByText(/Premium/i);
  const tierBody = article?.querySelector('.tier-body');
  expect(tierBody?.contains(premium)).toBe(false);
  // Dark card styling class present
  expect(article?.classList.contains('dark-card')).toBe(true);
  // "Not sure which fits?" line appears after the enterprise article
  const notSure = screen.getByText('Not sure which fits?');
  const pos = article?.compareDocumentPosition(notSure) ?? 0;
  expect(pos & Node.DOCUMENT_POSITION_FOLLOWING).toBe(Node.DOCUMENT_POSITION_FOLLOWING);
});"
    },
