The site sitemap (public/sitemap.xml) includes only five pages (/, /services, /training, /about, /contact) but the requirements R192-R194 require seven pages, including /systems and /engagements.
*/

import * as fs from 'fs';
import * as path from 'path';

describe('REPRO: Sitemap missing required pages /systems and /engagements', () => {
  test('public/sitemap.xml contains URLs for /systems and /engagements', () => {
