577:   .steps::before { content: ""; position: absolute; top: 24px; left: 12.5%; right: 12.5%; height: 2px; background: var(--color-accent); z-index: 0; }
578:   .steps li { text-align: center; }
579:   .steps .step-num { position: relative; z-index: 1; margin-left: auto; margin-right: auto; }
580:   .step-num { position: relative; z-index: 1; box-shadow: 0 0 0 8px var(--color-white); }
581:   .why-layout { grid-template-columns: 5fr 7fr; gap: var(--space-7); }
