583:   .service-layout { grid-template-columns: 5fr 7fr; gap: var(--space-7); }
584:   .service-items { grid-template-columns: repeat(2, 1fr); gap: var(--space-5); }
585:   .system-layout { grid-template-columns: 7fr 5fr; gap: var(--space-7); }
586:   .system-section.flip .system-text { order: 2; }
587:   .system-section.flip .system-art { order: 1; }
588:   .deliverable-grid { grid-template-columns: repeat(3, 1fr); gap: var(--space-5); }
589:   .tier-grid { grid-template-columns: repeat(3, 1fr); gap: var(--space-6); }
590:   .tier-body { padding: var(--space-6); }
591:   .tier-card.premium { display: grid; grid-template-columns: 5fr 7fr; }
592:   .tier-card.premium .tier-photo { height: 100%; }
593:   .tier-card.premium .tier-photo img { height: 100%; min-height: 360px; }
594:   .tier-card.premium .tier-body { padding: var(--space-7); }
595:   .course-grid { grid-template-columns: repeat(3, 1fr); }
596:   .about-grid.values { grid-template-columns: repeat(4, 1fr); }
597:   .split { grid-template-columns: 5fr 7fr; gap: var(--space-7); }
598:   .contact-grid { grid-template-columns: 7fr 5fr; gap: var(--space-6); align-items: start; }
599:   .testimonial blockquote { font-size: 2rem; }
600:   .nav-desktop { display: flex; }
601:   .menu-toggle, .nav-mobile { display: none; }
602:   .footer-inner { grid-template-columns: 2fr 1fr 1fr 1fr; gap: var(--space-6); }
603:   .training-banner { min-height: 400px; }
604: }
