606: /* Scroll targets: keep the section padding, eyebrow and neighbouring context visible below the sticky header. */
607: main h2 { scroll-margin-top: calc(var(--header-h) + 100px); }
608: main .page-hero p { scroll-margin-top: 420px; }
609: main .hero-text p { scroll-margin-top: 420px; }
610: main .cred-item span { scroll-margin-top: 520px; }
611: main .engagement { scroll-margin-top: 360px; }
612: main .steps p { scroll-margin-top: 420px; }
613: .site-footer .footer-brand p, .site-footer .footer-copy { scroll-margin-top: 520px; }
614: @media (min-width: 1024px) {
615:   main h2 { scroll-margin-top: calc(var(--header-h) + 132px); }
616:   main .cred-item span { scroll-margin-top: 600px; }
617:   main .steps p { scroll-margin-top: 340px; }
618: }
619: 
620: @media (prefers-reduced-motion: reduce) {
621:   *, *::before, *::after {
622:     transition: none !important;
623:     animation: none !important;
624:     transform: none !important;
625:     scroll-behavior: auto !important;
626:   }
627: }
