513: /* Footer */
514: .site-footer { background: var(--color-navy-deep); color: var(--color-white); padding: var(--space-8) 0 var(--space-6); }
515: .footer-inner { display: grid; gap: var(--space-6); }
516: .footer-brand p { color: var(--color-muted-on-dark); margin: var(--space-3) 0 var(--space-2); }
517: .footer-email { color: var(--color-accent-light); font-weight: 600; }
518: .footer-heading {
519:   font-family: var(--font-mono); font-size: var(--text-eyebrow); text-transform: uppercase; letter-spacing: .12em;
520:   color: var(--color-accent-light); margin: 0 0 var(--space-3); line-height: 1.5;
521: }
522: .footer-col ul, .footer-nav ul { list-style: none; display: grid; gap: var(--space-1); }
523: .footer-col a, .footer-nav a { color: var(--color-white); display: inline-flex; align-items: center; min-height: 40px; }
524: .footer-col a:hover, .footer-nav a:hover { color: var(--color-accent-light); }
525: .footer-bottom { margin-top: var(--space-7); padding-top: var(--space-5); border-top: 1px solid rgba(255,255,255,.14); }
526: .footer-copy { color: var(--color-muted-on-dark); margin: 0; font-size: var(--text-small); }
527: 
528: /* Architecture diagram */
529: .arch-diagram { width: 100%; }
530: .arch-svg { display: block; width: 100%; height: auto; }
531: .arch-stacked { display: none; max-width: 420px; margin: 0 auto; }
532: .diagram-text { font-family: var(--font-mono); }
533: @media (max-width: 767px) {
