559:   h1 { font-size: 3rem; line-height: 1.17; }
560:   h2 { font-size: 2.625rem; line-height: 1.19; }
561:   h3 { font-size: 1.375rem; }
562:   .lead { font-size: 1.3125rem; }
563:   .section, .page-hero, .systems-band, .deliverables, .testimonial, .cta-band { padding-top: var(--space-10); padding-bottom: var(--space-10); }

